function leaveLocalDraft(): DraftEnvelope { return { schemaVersion: 1, revision: 9, updatedAt: '2026-10-03T00:00:00Z', data: { ...structuredClone(emptyData), title: '本地原稿' } }; }
function leaveRepository() {
  const original = leaveLocalDraft(); localStorage.setItem(LEGACY_KEY, JSON.stringify(original));
  return { load: vi.fn<DraftRepository['load']>(() => structuredClone(original)), save: vi.fn<DraftRepository['save']>((draft) => { localStorage.setItem(LEGACY_KEY, JSON.stringify(draft)); }) };
}
function leaveLocalHost(repository: DraftRepository, provider = false) { const workspace = <NavigationPreference><LessonPlanWorkspace services={{ repository, lessonApi: services() }} /></NavigationPreference>; return render(provider ? <NavigationGuardProvider>{workspace}</NavigationGuardProvider> : workspace); }
async function leaveEdit(title = '快速导航本地新稿') { await screen.findByLabelText('课题'); fireEvent.change(screen.getByLabelText('课题'), { target: { value: title } }); }
function LocalPendingLeaveHarness() {
  const editor = useLessonEditor(), doc = useLessonDocument(); const [result, setResult] = useState('尚未决定'), [, repaint] = useState(0);
  const pendingOperationRef = doc.pendingOperation;
  if (!editor.ready) return <p>正在恢复隔离本地稿</p>;
  return <><LeaveProtection /><input aria-label="本地保护正文" value={editor.data.title} onChange={(event) => editor.set({ title: event.target.value })} /><button onClick={() => { pendingOperationRef.current = { busy: true, unknown: false }; repaint((value) => value + 1); }}>设置创建在途</button><button onClick={() => { pendingOperationRef.current = { busy: false, unknown: true }; repaint((value) => value + 1); }}>设置导入未知</button><button onClick={async () => setResult(await doc.leave.current?.() ? '允许离开' : '保持当前稿')}>请求本地离开</button><output aria-label="本地离开结果">{result}</output></>;
}
function pendingLeaveHost(repository: DraftRepository) { return render(<NavigationPreference><DocumentGateway services={{ repository, lessonApi: services() }}><LocalPendingLeaveHarness /></DocumentGateway></NavigationPreference>); }
