function realPage<T>(rows: T[], query: { offset?: number; limit?: number } = {}, fault?: SourceFault) {
  if (!query.limit || query.limit > 200) throw new ApiError('VALIDATION', '真实公开上限200', 422, false);
  const offset = query.offset ?? 0;
  if (offset > 0 && fault === 'failure') throw new ApiError('READ_FAILED', '后页读取失败，未采用半份来源', 503, true);
  return { items: offset > 0 && fault === 'empty' ? [] : rows.slice(offset, offset + query.limit), total: offset > 0 && fault === 'invalid-total' ? Number.NaN : offset > 0 && fault === 'changed-total' ? rows.length + 1 : rows.length, offset: offset > 0 && fault === 'wrong-offset' ? 0 : offset, limit: query.limit };
}
